package ansifilter

import "fmt"

// Codepage 437 character codes used by the TeX and RTF escape tables. These
// mirror the non-Windows branch of ansifilter's charcodes.h.
const (
	aumlLC   = 164
	oumlLC   = 182
	uumlLC   = 188
	aumlUC   = 132
	oumlUC   = 150
	uumlUC   = 156
	aacuteLC = 161
	eacuteLC = 169
	oacuteLC = 179
	uacuteLC = 186
	aacuteUC = 129
	eacuteUC = 137
	oacuteUC = 147
	uacuteUC = 154
	agraveLC = 160
	egraveLC = 168
	ograveLC = 178
	ugraveLC = 185
	agraveUC = 128
	egraveUC = 136
	ograveUC = 146
	ugraveUC = 153
	szlig    = 159
)

// texGenerator emits a plain TeX document.
type texGenerator struct{ *Generator }

func newTeXGenerator() *texGenerator {
	g := newGenerator(TEX)
	t := &texGenerator{g}
	g.f = t
	// \leavevmode makes TeX honor every paragraph it encounters.
	g.newLineTag = "\\leavevmode\\par\n"
	g.styleCommentOpen = "%"
	g.spacer = "\\ "
	return t
}

func (t *texGenerator) openTag() string {
	var s string
	e := &t.elementStyle
	if e.IsBold() {
		s += "\\bf"
	}
	if e.IsItalic() {
		s += "\\it"
	}
	c := e.FgColor()
	s += "\\textColor{" + c.Red(TEX) + " " + c.Green(TEX) + " " + c.Blue(TEX) + " 0}"
	return "{" + s
}

func (t *texGenerator) closeTag() string { return "}" }

func (t *texGenerator) generatorComment() string {
	return "% TeX generated by ansifilter " + Version + ", " + URL + "\n"
}

func (t *texGenerator) header() string {
	s := t.styleCommentOpen + t.docTitle + "\n" +
		"\\nopagenumbers\n" +
		"\\input colordvi\n"
	if t.styleSheetPath != "" {
		s += "\\input " + t.styleSheetPath + "\n"
	}
	s += "{\n" + "\\tt\n"
	return s
}

func (t *texGenerator) footer() string {
	footer := "\n}\n\\bye\n"
	if !t.omitVersionInfo {
		footer += t.generatorComment()
	}
	return footer
}

func (t *texGenerator) body() { t.processInput() }

func (t *texGenerator) lineNum() {
	if t.showLineNumbers {
		if t.numberCurrentLine {
			if t.lineNumber > 1 {
				t.write(t.f.closeTag())
			}
			t.write("{\\textColor{1 1 1 0} " + fmt.Sprintf("%5d", t.lineNumber) + t.spacer + "}")
			t.write(t.f.openTag())
		}
	}
}

func (t *texGenerator) maskChar(c byte) string {
	switch c {
	case '{', '}':
		return "$\\" + chr(c) + "$"
	case '^':
		return "{\\bf\\^{}}"
	case '_', '&', '$', '#', '%':
		return "\\" + chr(c) + "{}"
	case '\\':
		return "$\\backslash$"
	case ' ':
		return t.spacer
	case '+', '-', '<', '>', '=':
		return "$\\mathord{" + chr(c) + "}$"
	case aumlLC:
		return "\\\"a"
	case oumlLC:
		return "\\\"o"
	case uumlLC:
		return "\\\"u"
	case aumlUC:
		return "\\\"A"
	case oumlUC:
		return "\\\"O"
	case uumlUC:
		return "\\\"U"
	case aacuteLC:
		return "\\'a"
	case eacuteLC:
		return "\\'e"
	case oacuteLC:
		return "\\'o"
	case uacuteLC:
		return "\\'u"
	case agraveLC:
		return "\\`a"
	case egraveLC:
		return "\\`e"
	case ograveLC:
		return "\\`o"
	case ugraveLC:
		return "\\`u"
	case aacuteUC:
		return "\\'A"
	case eacuteUC:
		return "\\'E"
	case oacuteUC:
		return "\\'O"
	case uacuteUC:
		return "\\'U"
	case agraveUC:
		return "\\`A"
	case egraveUC:
		return "\\`E"
	// The original maps these two the other way round; preserved as-is so the
	// output matches byte for byte.
	case ugraveUC:
		return "\\`O"
	case ograveUC:
		return "\\`U"
	case szlig:
		return "\\ss "
	case '\t':
		return "\t"
	default:
		if c > 0x1f {
			return chr(c)
		}
		return ""
	}
}
